export interface UsageLedgerEntry extends AgentExecutionUsage {
  executionId: number;
  phase: PromptPhase;
  issueId?: IssueId;
  attempt?: number;
  client: PromptClientKind;
  model?: string;
  outcome: "succeeded" | "failed";
  error?: string;
}

export interface UsageTotals {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  reasoningTokens: number;
  totalTokens: number;
  costUsd: number;
  hasUnknownTokens: boolean;
  hasUnknownCost: boolean;
}

export interface UsageSummary {
  run: UsageTotals;
  byIssue: Record<string, UsageTotals>;
  byPhase: Record<PromptPhase, UsageTotals>;
}

export interface PromptManifestEntry {
  phase: PromptPhase;
  issueId?: string | number;
  attempt?: number;
  model?: string;
  client: PromptClientKind;
  path: string;
  sha256: string;
  createdAt: string;
  /** Additive structured metadata for entries that carry extra context (e.g. live-steering overrides). */
  metadata?: Record<string, unknown>;
}

export interface SchedulerProgress {
  iterationsStarted?: number;
  skippedIds?: IssueId[];
}

/**
 * The Loop Run's authoritative snapshot of run state. The Durable Loop
 * Run Tracker persists this shape; nothing else owns it.
 */
export interface RunSnapshot {
  runId: string;
  revision: number;
  repoCwd: string;
  startCommit: string;
  status: RunStatus;
  terminalReason?: TerminalReason;
  panicUndo?: PanicUndoState;
  owner: { pid: number; heartbeatAt: string };
  scheduler: SchedulerSnapshot;
  tasks: Record<string, TaskRecord>;
  review: { phase: ReviewPhase };
  rollbackSnapshotId?: string;
  promptTranscripts: PromptTranscriptsState;
  usageLedger: UsageLedgerEntry[];
  usageSummary: UsageSummary;
}

/**
 * Pure usage summary builder.
 *
 * Stateless and independent of file I/O so it can be tested without a
 * tracker. The Usage Ledger is the source of truth; after each ledger
 * append the Usage Summary is recomputed from the full ledger.
 *
 * See ADR-0009.
 */

import type {
  AgentExecutionUsage,
  UsageLedgerEntry,
  UsageSummary,
  UsageTotals,
  PromptPhase,
} from "./state.js";

const TOKEN_FIELDS: Array<Exclude<keyof AgentExecutionUsage, "perModelUsage" | "totalTokens" | "costUsd" | "contextTokens" | "maxContext">> = [
  "inputTokens",
  "outputTokens",
  "cacheReadTokens",
  "cacheWriteTokens",
  "reasoningTokens",
];

function zeroTotals(): UsageTotals {
  return {
    inputTokens: 0,
    outputTokens: 0,
    cacheReadTokens: 0,
    cacheWriteTokens: 0,
    reasoningTokens: 0,
    totalTokens: 0,
    costUsd: 0,
    hasUnknownTokens: false,
    hasUnknownCost: false,
  };
}

function accumulateInto(target: UsageTotals, entry: UsageLedgerEntry): void {
  for (const field of TOKEN_FIELDS) {
    const val = entry[field];
    if (val !== null) {
      target[field] += val;
    }
  }
  if (entry.totalTokens === null) {
    target.hasUnknownTokens = true;
  } else {
    target.totalTokens += entry.totalTokens;
  }
  if (entry.costUsd === null) {
    target.hasUnknownCost = true;
  } else {
    target.costUsd += entry.costUsd;
  }
}

/**
 * Recompute the full Usage Summary from the Usage Ledger.
 *
 * Aggregates known numeric values and sets `hasUnknownTokens` /
 * `hasUnknownCost` flags when any relevant field is `null`. Groups
 * totals by run, by issue, and by phase.
 */
export function buildUsageSummary(ledger: UsageLedgerEntry[]): UsageSummary {
  const run = zeroTotals();
  const byIssue: Record<string, UsageTotals> = {};
  const byPhase: Record<PromptPhase, UsageTotals> = {
    implement: zeroTotals(),
    verify: zeroTotals(),
    merger: zeroTotals(),
    review: zeroTotals(),
    // Live steering messages are recorded as prompt artifacts but do not generate
    // token-usage ledger entries. The key must exist for type completeness.
    "live-steering": zeroTotals(),
  };

  for (const entry of ledger) {
    accumulateInto(run, entry);

    if (entry.issueId != null) {
      const key = String(entry.issueId);
      if (!byIssue[key]) {
        byIssue[key] = zeroTotals();
      }
      accumulateInto(byIssue[key], entry);
    }

    accumulateInto(byPhase[entry.phase], entry);
  }

  return { run, byIssue, byPhase };
}

import type { AgentExecutionUsage, IssueId, TaskMeta, TaskPhase, UsageLedgerEntry, UsageTotals } from "./state.js";
import type { DashboardSelection } from "./ink-log-projection.js";

export interface PhaseRecord {
  contextTokens: number | null;
  maxContext: number | null;
}

export interface WorkerDashboardRow {
  issueId: IssueId;
  phase: TaskPhase;
  phases: ReadonlyMap<TaskPhase, PhaseRecord>;
  title: string | null;
  latestAt: string | null;
  latestInputTokens: number | null;
  latestContextTokens: number | null;
  usage: UsageTotals;
  /** In-progress cumulative usage from the current execution. Cleared when usageRecorded fires. */
  streamingUsage: AgentExecutionUsage | null;
}

export interface WorkerProjectionState {
  readonly workerOrder: readonly IssueId[];
  readonly workers: ReadonlyMap<string, WorkerDashboardRow>;
  readonly runUsage: UsageTotals;
  readonly runStreamingUsage: AgentExecutionUsage | null;
}

export function zeroUsageTotals(): UsageTotals {
  return {
    inputTokens: 0,
    outputTokens: 0,
    cacheReadTokens: 0,
    cacheWriteTokens: 0,
    reasoningTokens: 0,
    totalTokens: 0,
    costUsd: 0,
    hasUnknownTokens: false,
    hasUnknownCost: false,
  };
}

export function createWorkerProjectionState(): WorkerProjectionState {
  return {
    workerOrder: [],
    workers: new Map(),
    runUsage: zeroUsageTotals(),
    runStreamingUsage: null,
  };
}

export function accumulateUsage(target: UsageTotals, entry: UsageLedgerEntry): UsageTotals {
  return {
    inputTokens: target.inputTokens + (entry.inputTokens ?? 0),
    outputTokens: target.outputTokens + (entry.outputTokens ?? 0),
    cacheReadTokens: target.cacheReadTokens + (entry.cacheReadTokens ?? 0),
    cacheWriteTokens: target.cacheWriteTokens + (entry.cacheWriteTokens ?? 0),
    reasoningTokens: target.reasoningTokens + (entry.reasoningTokens ?? 0),
    totalTokens: target.totalTokens + (entry.totalTokens ?? 0),
    costUsd: target.costUsd + (entry.costUsd ?? 0),
    hasUnknownTokens: target.hasUnknownTokens || entry.totalTokens === null,
    hasUnknownCost: target.hasUnknownCost || entry.costUsd === null,
  };
}

export function accumulateStreamingUsage(target: UsageTotals, usage: AgentExecutionUsage): UsageTotals {
  return {
    inputTokens: target.inputTokens + (usage.inputTokens ?? 0),
    outputTokens: target.outputTokens + (usage.outputTokens ?? 0),
    cacheReadTokens: target.cacheReadTokens + (usage.cacheReadTokens ?? 0),
    cacheWriteTokens: target.cacheWriteTokens + (usage.cacheWriteTokens ?? 0),
    reasoningTokens: target.reasoningTokens + (usage.reasoningTokens ?? 0),
    totalTokens: target.totalTokens + (usage.totalTokens ?? 0),
    costUsd: target.costUsd + (usage.costUsd ?? 0),
    hasUnknownTokens: target.hasUnknownTokens || usage.totalTokens === null,
    hasUnknownCost: target.hasUnknownCost || usage.costUsd === null,
  };
}

export function workerKey(issueId: IssueId): string {
  return String(issueId);
}

export function withSelection(
  workerOrder: readonly IssueId[],
  currentSelection: DashboardSelection,
): DashboardSelection {
  if (currentSelection.kind === "allLogs") return currentSelection;
  const issueId = currentSelection.issueId;
  return workerOrder.some((id) => String(id) === String(issueId))
    ? currentSelection
    : { kind: "allLogs" };
}

function updateWorkerMeta(
  row: WorkerDashboardRow,
  meta: TaskMeta | undefined,
): WorkerDashboardRow {
  return {
    ...row,
    title: meta?.title ?? row.title,
  };
}

function createWorkerRow(issueId: IssueId, phase: TaskPhase): WorkerDashboardRow {
  return {
    issueId,
    phase,
    phases: new Map<TaskPhase, PhaseRecord>(),
    title: null,
    latestAt: null,
    latestInputTokens: null,
    latestContextTokens: null,
    usage: zeroUsageTotals(),
    streamingUsage: null,
  };
}

export function getWorkerRows(state: WorkerProjectionState): WorkerDashboardRow[] {
  return state.workerOrder
    .map((issueId) => state.workers.get(workerKey(issueId)))
    .filter((row): row is WorkerDashboardRow => row !== undefined);
}

export function getSelectedWorker(
  state: WorkerProjectionState & { dashboardSelection: DashboardSelection },
): WorkerDashboardRow | null {
  if (state.dashboardSelection.kind === "allLogs") return null;
  return state.workers.get(workerKey(state.dashboardSelection.issueId)) ?? null;
}

export function getWorkerPhase(
  state: WorkerProjectionState,
  issueId: IssueId | undefined,
): TaskPhase | undefined {
  if (issueId === undefined) return undefined;
  return state.workers.get(workerKey(issueId))?.phase;
}

export function touchWorkerLatestAt(
  state: WorkerProjectionState,
  issueId: IssueId | undefined,
  at: string,
): Pick<WorkerProjectionState, "workers"> | null {
  if (issueId === undefined) return null;
  const key = workerKey(issueId);
  const row = state.workers.get(key);
  if (!row) return null;
  const workers = new Map(state.workers);
  workers.set(key, { ...row, latestAt: at });
  return { workers };
}

export function applyTaskPhaseToWorkerProjection(
  state: WorkerProjectionState & { dashboardSelection: DashboardSelection },
  event: { issueId: IssueId; to: TaskPhase; meta?: TaskMeta },
  at: string,
): Pick<WorkerProjectionState & { dashboardSelection: DashboardSelection }, "workers" | "workerOrder" | "dashboardSelection"> {
  const key = workerKey(event.issueId);
  const workers = new Map(state.workers);
  const existing = workers.get(key) ?? createWorkerRow(event.issueId, event.to);
  const phases = existing.phases.has(event.to)
    ? existing.phases
    : new Map([...existing.phases, [event.to, { contextTokens: null, maxContext: null }]]);
  workers.set(key, updateWorkerMeta({ ...existing, phase: event.to, phases, latestAt: at }, event.meta));

  const workerOrder = state.workerOrder.some((issueId) => String(issueId) === key)
    ? [...state.workerOrder]
    : [...state.workerOrder, event.issueId];

  return {
    workers,
    workerOrder,
    dashboardSelection: withSelection(workerOrder, state.dashboardSelection),
  };
}

export function applyTaskMetaToWorkerProjection(
  state: WorkerProjectionState,
  issueId: IssueId,
  meta: TaskMeta | undefined,
): Pick<WorkerProjectionState, "workers"> | null {
  const key = workerKey(issueId);
  const existing = state.workers.get(key);
  if (!existing) return null;
  const workers = new Map(state.workers);
  workers.set(key, updateWorkerMeta(existing, meta));
  return { workers };
}

export function applyUsageRecordedToWorkerProjection(
  state: WorkerProjectionState,
  entry: UsageLedgerEntry,
  at: string,
): Pick<WorkerProjectionState, "runUsage" | "runStreamingUsage"> | Pick<WorkerProjectionState, "workers" | "runUsage"> {
  const runUsage = accumulateUsage(state.runUsage, entry);
  if (entry.issueId === undefined) {
    return { runUsage, runStreamingUsage: null };
  }

  const workers = new Map(state.workers);
  const key = workerKey(entry.issueId);
  const existing = workers.get(key) ?? createWorkerRow(entry.issueId, "scheduled");
  const currentPhase = existing.phase;
  const phaseRecord = existing.phases.get(currentPhase) ?? { contextTokens: null, maxContext: null };
  const updatedPhases = new Map(existing.phases);
  updatedPhases.set(currentPhase, {
    ...phaseRecord,
    contextTokens: entry.contextTokens ?? phaseRecord.contextTokens,
    maxContext: entry.maxContext ?? phaseRecord.maxContext,
  });
  workers.set(key, {
    ...existing,
    phases: updatedPhases,
    latestAt: at,
    latestInputTokens: entry.inputTokens,
    latestContextTokens: entry.contextTokens ?? existing.latestContextTokens,
    usage: accumulateUsage(existing.usage, entry),
    streamingUsage: null,
  });
  return { workers, runUsage };
}

export function applyStreamingUsageToWorkerProjection(
  state: WorkerProjectionState,
  issueId: IssueId | undefined,
  usage: AgentExecutionUsage,
): Pick<WorkerProjectionState, "runStreamingUsage"> | Pick<WorkerProjectionState, "workers"> | null {
  if (issueId === undefined) {
    return { runStreamingUsage: usage };
  }
  const key = workerKey(issueId);
  const workers = new Map(state.workers);
  const existing = workers.get(key);
  if (!existing) return null;
  const currentPhase = existing.phase;
  const phaseRecord = existing.phases.get(currentPhase) ?? { contextTokens: null, maxContext: null };
  const updatedPhases = new Map(existing.phases);
  updatedPhases.set(currentPhase, {
    contextTokens: usage.contextTokens ?? phaseRecord.contextTokens,
    maxContext: usage.maxContext ?? phaseRecord.maxContext,
  });
  workers.set(key, {
    ...existing,
    phases: updatedPhases,
    streamingUsage: usage,
    latestInputTokens: usage.inputTokens,
    latestContextTokens: usage.contextTokens ?? existing.latestContextTokens,
  });
  return { workers };
}

export function displayRunUsage(state: WorkerProjectionState): UsageTotals {
  let totals = zeroUsageTotals();
  for (const worker of state.workers.values()) {
    if (worker.streamingUsage !== null) {
      totals = accumulateStreamingUsage(totals, worker.streamingUsage);
    }
  }
  if (state.runStreamingUsage !== null) {
    totals = accumulateStreamingUsage(totals, state.runStreamingUsage);
  }
  return totals;
}

export function hasInProgressUsage(state: WorkerProjectionState): boolean {
  const totals = displayRunUsage(state);
  return totals.inputTokens > 0
    || totals.outputTokens > 0
    || totals.cacheReadTokens > 0
    || totals.cacheWriteTokens > 0
    || totals.reasoningTokens > 0
    || totals.totalTokens > 0
    || totals.costUsd > 0
    || totals.hasUnknownTokens
    || totals.hasUnknownCost;
}

export function displayInputTokens(worker: WorkerDashboardRow): number {
  return worker.usage.inputTokens + (worker.streamingUsage?.inputTokens ?? 0);
}

export function displayOutputTokens(worker: WorkerDashboardRow): number {
  return worker.usage.outputTokens + (worker.streamingUsage?.outputTokens ?? 0);
}

export function displayHasUnknownCost(worker: WorkerDashboardRow): boolean {
  if (worker.usage.hasUnknownCost) return true;
  return worker.streamingUsage !== null && worker.streamingUsage.costUsd === null;
}

