import { describe, expect, it } from "vitest";

import {
  appendRunLogEntryToInkState,
  applyLoopRunEventToInkState,
  createInkRunViewState,
  displayInputTokens,
  displayOutputTokens,
  displayRunUsage,
  formatContextWindowFill,
  formatDisplayCost,
  formatUsageCost,
  getVisibleLogEntries,
  getWorkerRows,
  reduceInkUiAction,
} from "../src/core/loop-run/ink-state.js";

function usageRecordedEvent(issueId: number, overrides: Partial<Parameters<typeof applyLoopRunEventToInkState>[1] & { entry: Record<string, unknown> }> = {}) {
  return {
    kind: "usageRecorded" as const,
    entry: {
      executionId: 1,
      phase: "implement" as const,
      issueId,
      client: "pi" as const,
      outcome: "succeeded" as const,
      inputTokens: 166000,
      outputTokens: 5000,
      cacheReadTokens: null,
      cacheWriteTokens: null,
      reasoningTokens: null,
      totalTokens: 171000,
      costUsd: 1.25,
      ...((overrides as { entry?: Record<string, unknown> }).entry ?? {}),
    },
  };
}

describe("ink log state", () => {
  it("builds a merged timeline in sequence order across workers", () => {
    let state = createInkRunViewState({ maxContext: 272000 });

    state = appendRunLogEntryToInkState(state, { kind: "issue-text", issueId: 1, text: "alpha\n" }, "2026-06-25T10:00:00.000Z");
    state = appendRunLogEntryToInkState(state, { kind: "issue-text", issueId: 2, text: "beta\n" }, "2026-06-25T10:00:01.000Z");
    state = appendRunLogEntryToInkState(state, { kind: "issue-text", issueId: 1, text: "gamma\n" }, "2026-06-25T10:00:02.000Z");

    expect(getVisibleLogEntries(state, 10).map((entry) => [entry.sequence, entry.issueId, entry.text])).toEqual([
      [1, 1, "alpha"],
      [2, 2, "beta"],
      [3, 1, "gamma"],
    ]);
  });

  it("keeps only the newest log entries in memory", () => {
    let state = createInkRunViewState({ maxContext: null });

    for (let i = 0; i < 1_050; i++) {
      state = appendRunLogEntryToInkState(state, { kind: "text", text: `line-${i}\n` }, "2026-06-25T10:00:00.000Z");
    }

    const visible = getVisibleLogEntries(state, 1_050);
    expect(visible).toHaveLength(1_000);
    expect(visible[0]!.text).toBe("line-50");
    expect(visible.at(-1)!.text).toBe("line-1049");
  });

  it("keeps only a bounded text tail for a huge log entry", () => {
    let state = createInkRunViewState({ maxContext: null });

    state = appendRunLogEntryToInkState(
      state,
      { kind: "text", text: `start-${"x".repeat(1_000_050)}-end\n` },
      "2026-06-25T10:00:00.000Z",
    );

    const visible = getVisibleLogEntries(state, 10);
    expect(visible).toHaveLength(1);
    expect(visible[0]!.text.length).toBeLessThanOrEqual(1_000_000);
    expect(visible[0]!.text).not.toContain("start-");
    expect(visible[0]!.text).toContain("-end");
  });

  it("moves selection to worker and filters logs, then back to All logs shows all", () => {
    let state = createInkRunViewState({ maxContext: null });
    state = applyLoopRunEventToInkState(state, { kind: "taskPhaseChanged", issueId: 1, from: null, to: "implementing", meta: { title: "One" } }, "2026-06-25T10:00:00.000Z");
    state = applyLoopRunEventToInkState(state, { kind: "taskPhaseChanged", issueId: 2, from: null, to: "implementing", meta: { title: "Two" } }, "2026-06-25T10:00:01.000Z");
    state = appendRunLogEntryToInkState(state, { kind: "issue-text", issueId: 1, text: "alpha\n" }, "2026-06-25T10:00:02.000Z");
    state = appendRunLogEntryToInkState(state, { kind: "issue-text", issueId: 2, text: "beta\n" }, "2026-06-25T10:00:03.000Z");

    expect(state.dashboardSelection).toEqual({ kind: "allLogs" });

    state = reduceInkUiAction(state, { kind: "moveSelection", delta: 1 });
    expect(state.dashboardSelection).toEqual({ kind: "worker", issueId: 1 });
    expect(getVisibleLogEntries(state, 10).map((entry) => entry.text)).toEqual(["alpha"]);

    state = reduceInkUiAction(state, { kind: "moveSelection", delta: -1 });
    expect(state.dashboardSelection).toEqual({ kind: "allLogs" });
    expect(getVisibleLogEntries(state, 10).map((entry) => entry.text)).toEqual(["alpha", "beta"]);
  });

  it("moves between follow-latest and manual scroll", () => {
    let state = createInkRunViewState({ maxContext: null });
    state = appendRunLogEntryToInkState(state, { kind: "text", text: "one\n" }, "2026-06-25T10:00:00.000Z");
    state = appendRunLogEntryToInkState(state, { kind: "text", text: "two\n" }, "2026-06-25T10:00:01.000Z");
    state = appendRunLogEntryToInkState(state, { kind: "text", text: "three\n" }, "2026-06-25T10:00:02.000Z");

    state = reduceInkUiAction(state, { kind: "pageUp", pageSize: 2 });
    expect(state.followMode).toEqual({ kind: "manualScroll", offsetFromBottom: 2 });

    state = reduceInkUiAction(state, { kind: "pageDown", pageSize: 1 });
