export class LoopRunTracker {
  private readonly runsDir: string;
  private readonly activeFilePath: string;
  private readonly archiveDir: string;

  constructor(private readonly cwd: string) {
    this.runsDir = join(cwd, RUNS_DIR);
    this.activeFilePath = join(this.runsDir, ACTIVE_FILE);
    this.archiveDir = join(this.runsDir, ARCHIVE_DIR);
  }

  create(params: {
    runId: string;
    repoCwd: string;
    startCommit: string;
    scheduler: {
      maxIterations: number;
      maxParallel: number;
      skippedIds: IssueId[];
    };
    rollbackSnapshotId?: string;
    capturePromptTranscripts?: boolean;
  }): RunSnapshot {
    const promptTranscripts =
      params.capturePromptTranscripts === false
        ? { enabled: false as const }
        : { enabled: true as const };

    const state: RunSnapshot = {
      runId: params.runId,
      revision: 1,
      repoCwd: params.repoCwd,
      startCommit: params.startCommit,
      status: "running",
      owner: {
        pid: process.pid,
        heartbeatAt: new Date().toISOString(),
      },
      scheduler: {
        maxIterations: params.scheduler.maxIterations,
        iterationsStarted: 0,
        maxParallel: params.scheduler.maxParallel,
        skippedIds: params.scheduler.skippedIds,
      },
      tasks: {},
      review: { phase: "pending" },
      rollbackSnapshotId: params.rollbackSnapshotId,
      promptTranscripts,
      usageLedger: [],
      usageSummary: buildUsageSummary([]),
    };

    this.atomicWrite(state);
    return state;
  }

  read(): RunSnapshot | null {
    this.cleanupTempFile();
    if (!existsSync(this.activeFilePath)) return null;
    const raw = readFileSync(this.activeFilePath, "utf8");
    return normalizeRunSnapshot(JSON.parse(raw) as RunSnapshot);
  }

  private cleanupTempFile(): void {
    const tmpPath = this.activeFilePath + ".tmp";
    if (existsSync(tmpPath) && !existsSync(this.activeFilePath)) {
      renameSync(tmpPath, this.activeFilePath);
    }
  }

  /**
   * Escape-hatch reducer-style update for callers that need to mutate
   * multiple snapshot fields atomically (e.g. stale-run recovery
   * restart surgery). Normal phase / meta / scheduler / review writes
   * should go through the targeted methods below.
   */
  update(updater: (state: RunSnapshot) => RunSnapshot): RunSnapshot {
    const current = this.read();
    if (!current) {
      throw new Error("Cannot update: no active tracker state found");
    }
    const next = updater(current);
    next.revision = current.revision + 1;
    this.atomicWrite(next);
    return next;
  }

  updateHeartbeat(): RunSnapshot {
    return this.update((s) => ({
      ...s,
      owner: { ...s.owner, heartbeatAt: new Date().toISOString() },
    }));
  }


