export const MIN_TERMINAL_COLUMNS = 100;
export const MIN_TERMINAL_ROWS = 30;

type TerminalSizeState =
  | { kind: "normal"; columns: number; rows: number }
  | { kind: "tooSmall"; columns: number; rows: number; minColumns: number; minRows: number };

function getTerminalSizeState(
  terminalSize: { columns: number; rows: number } | undefined,
): TerminalSizeState {
  const columns = terminalSize?.columns ?? MIN_TERMINAL_COLUMNS;
  const rows = terminalSize?.rows ?? MIN_TERMINAL_ROWS;
  if (columns < MIN_TERMINAL_COLUMNS || rows < MIN_TERMINAL_ROWS) {
    return { kind: "tooSmall", columns, rows, minColumns: MIN_TERMINAL_COLUMNS, minRows: MIN_TERMINAL_ROWS };
  }
  return { kind: "normal", columns, rows };
}

const workerColors = [
  "#FF6482",  // pink
  "#64D2FF",  // sky blue
  "#30D158",  // green
  "#FFD60A",  // yellow
  "#BF5AF2",  // purple
  "#FF9F0A",  // orange
  "#5E5CE6",  // indigo
  "#AC8E68",  // tan
] as const;

function workerColor(issueId: IssueId | undefined): string | undefined {
  if (issueId === undefined) return "gray";
  const numericId = typeof issueId === "number"
    ? issueId
    : Array.from(issueId).reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
  return workerColors[numericId % workerColors.length];
}


